     1	//! The stems an audio export writes beside its mix (spec §11 AU-108): which
     2	//! timeline tracks each file holds and what it is called. Swift writes them
     3	//! (`ExportStems.swift`); this answers only the grouping and the names, so
     4	//! the sheet, the `export` tool and the tests read one list.
     5	//!
     6	//! The rules:
     7	//!
     8	//! - **Heard.** A timeline track is heard when the plan has an audio track
     9	//!   labelled with it (`CompTrack::track`, AU-107 — so a track holding only
    10	//!   pictures, or nothing, is not) and it is not `silenced` among the
    11	//!   timeline's tracks (mute, solo). None heard is refused.
    12	//! - **Grouping.** `tracks`: one stem per heard track. `names`: heard tracks
    13	//!   whose trimmed names match case-insensitively are one stem, named by the
    14	//!   first's spelling; an unnamed track is its own.
    15	//! - **Order.** Timeline order of each stem's first track; a stem's tracks
    16	//!   in timeline order.
    17	//! - **Names.** The trimmed track name, else `Track N` (N = its index + 1,
    18	//!   the header's label), with `/` and `:` replaced by `-`; a name equal
    19	//!   case-insensitively to an earlier stem's gets ` (Track N)` of its first
    20	//!   track, and one still equal to an earlier stem's then gets
    21	//!   ` (Track N, 2)`, ` (Track N, 3)` and on, the first no earlier stem
    22	//!   holds, so no two stems share a file.
    23	
    24	use std::collections::BTreeSet;
    25	
    26	use serde_json::{Map, Value};
    27	
    28	use crate::audio::silenced;
    29	use crate::export_overrides::StemsMode;
    30	use crate::model::Project;
    31	
    32	/// One stem: the file's name (without the mix's) and the timeline tracks
    33	/// whose sound it holds.
    34	#[derive(Debug, Clone, PartialEq, Eq)]
    35	pub(crate) struct Stem {
    36	    pub(crate) name: String,
    37	    pub(crate) tracks: Vec<u32>,
    38	}
    39	
    40	impl Stem {
    41	    /// `{"name": …, "tracks": [ids]}`, the settings' `stems` entry.
    42	    pub(crate) fn to_json(&self) -> Value {
    43	        let mut out = Map::new();
    44	        out.insert("name".to_string(), Value::from(self.name.clone()));
    45	        let tracks = self.tracks.iter().map(|id| Value::from(*id)).collect();
    46	        out.insert("tracks".to_string(), Value::Array(tracks));
    47	        Value::Object(out)
    48	    }
    49	}
    50	
    51	/// A group while it is being gathered: its first track's index and the
    52	/// spelling it is named by.
    53	struct Group {
    54	    first: usize,
    55	    spelling: String,
    56	    tracks: Vec<u32>,
    57	}
    58	
    59	impl Project {
    60	    /// The stems `mode` asks for, in order (spec §11 AU-108 (b), (c)), or
    61	    /// the refusal when no track is heard.
    62	    pub(crate) fn export_stems(&self, mode: StemsMode) -> Result<Vec<Stem>, String> {
    63	        let labelled: BTreeSet<u32> = self.assign().audio.iter().map(|t| t.track).collect();
    64	        let mut groups: Vec<Group> = Vec::new();
    65	        for (index, track) in self.tracks.iter().enumerate() {
    66	            if !labelled.contains(&track.id) || silenced(&self.tracks, track) {
    67	                continue;
    68	            }
    69	            let trimmed = track.name.trim();
    70	            let joins = match mode {
    71	                StemsMode::Tracks => None,
    72	                StemsMode::Names if trimmed.is_empty() => None,
    73	                StemsMode::Names => groups
    74	                    .iter_mut()
    75	                    .find(|g| !g.spelling.is_empty() && same(&g.spelling, trimmed)),
    76	            };
    77	            match joins {
    78	                Some(group) => group.tracks.push(track.id),
    79	                None => groups.push(Group {
    80	                    first: index,
    81	                    spelling: trimmed.to_string(),
    82	                    tracks: vec![track.id],
    83	                }),
    84	            }
    85	        }
    86	        if groups.is_empty() {
    87	            return Err("stems: no track is heard, so there is no stem to write".to_string());
    88	        }
    89	        let mut stems: Vec<Stem> = Vec::with_capacity(groups.len());
    90	        for group in groups {
    91	            let label = format!("Track {}", group.first.saturating_add(1));
    92	            let base = if group.spelling.is_empty() {
    93	                label.clone()
    94	            } else {
    95	                group.spelling.replace(['/', ':'], "-")
    96	            };
    97	            let taken = |name: &str| stems.iter().any(|s| same(&s.name, name));
    98	            let mut name = base.clone();
    99	            if taken(&name) {
   100	                name = format!("{base} ({label})");
   101	            }
   102	            let mut count: u32 = 2;
   103	            while taken(&name) {
   104	                name = format!("{base} ({label}, {count})");
   105	                count = count.saturating_add(1);
   106	            }
   107	            stems.push(Stem {
   108	                name,
   109	                tracks: group.tracks,
   110	            });
   111	        }
   112	        Ok(stems)
   113	    }
   114	}
   115	
   116	/// Two names the same but for case.
   117	fn same(a: &str, b: &str) -> bool {
   118	    a.to_lowercase() == b.to_lowercase()
   119	}
[package]
name = "framejob-core"
version = "0.1.0"
edition = "2021"
license = "Apache-2.0"

[lib]
name = "framejob_core"
crate-type = ["staticlib", "rlib"]

[dependencies]
serde = { version = "1", features = ["derive"] }
# `preserve_order` is what `graphic` enables; a path dependency unifies it
# into this build anyway, so it is spelled here where a reader of the core
# will see it: `serde_json::Map` is insertion-ordered, and `recipe.rs`'s
# `content_hash` sorts before it hashes rather than lean on the map.
serde_json = { version = "1", features = ["preserve_order"] }
serde_path_to_error = "0.1.20"
tiny_http = "0.12"
# The CSS named-colour table `model_color.rs` reads (G-12): usvg 0.48.1's own
# pin, already in the lock through `graphic`, so a name the core stores is one
# the engine draws.
svgtypes = "0.16.1"
# The motion-graphics engine (road map 10, G-2): only `ffi_graphic.rs` names it.
graphic = { path = "../graphic" }
# The `.fjgraphic` manifest's checksums (`graphic_package.rs`, G-46 (c)); also
# `graphic_ffi.rs`'s and `graphic_package.rs`'s test oracles. Already in the
# lock through `graphic`.
sha2 = "0.10"

[profile.release]
# No LTO: cargo skips it for a staticlib+rlib unit anyway, and asking for it
# fat-LTOs each of the 32 test binaries (designs/adr/rust-build-settings.md).
incremental = true

[patch.crates-io]
# graphic's vendored tiny-skia with the gradient dither (spec §11 PR-13): Cargo ignores the
# [patch] in graphic/Cargo.toml when building this crate, so it is restated here.
tiny-skia = { path = "../graphic/vendor/tiny-skia" }
